#ifdef CONFIG_QKX_OWNER_GATE
/*
 * Custody is independent of protocol map counts and completion wakeups.
 * Only the two driver workers below may consume custody. Loss is sticky:
 * a wakeup or a later packet never authorizes freeing unknown DMA state.
 */
struct qkx_rpc_file_owner {
	struct list_head node;
	struct work_struct work;
	struct fastrpc_file *fl;
	struct task_struct *control_task;
	bool close_requested;
	bool release_done;
	bool queued;
	bool quarantined;
	int release_error;
	int loss_error;
};

struct qkx_rpc_ctx_owner {
	struct list_head node;
	struct work_struct work;
	struct smq_invoke_ctx *ctx;
	struct fastrpc_file *fl;
	struct task_struct *finalizer;
	unsigned int callbacks;
	bool operation;
	bool remote;
	bool terminal;
	bool unknown;
	bool retire;
	bool queued;
};

static DEFINE_SPINLOCK(qkx_rpc_lock);
static LIST_HEAD(qkx_rpc_files);
static LIST_HEAD(qkx_rpc_contexts);
static void fastrpc_file_destroy(struct kref *kref);
static int fastrpc_release_current_dsp_process(struct fastrpc_file *fl);
static void context_free(struct smq_invoke_ctx *ctx);

static struct qkx_rpc_file_owner *qkx_rpc_file_find(struct fastrpc_file *fl)
{
	struct qkx_rpc_file_owner *owner;

	list_for_each_entry(owner, &qkx_rpc_files, node)
		if (owner->fl == fl)
			return owner;
	return NULL;
}

static struct qkx_rpc_ctx_owner *qkx_rpc_ctx_find(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;

	list_for_each_entry(owner, &qkx_rpc_contexts, node)
		if (owner->ctx == ctx)
			return owner;
	return NULL;
}

static void qkx_rpc_file_kick(struct qkx_rpc_file_owner *owner)
{
	/* Every non-custodian get/put is serialized by qkx_rpc_lock. */
	if (owner->close_requested && !owner->control_task &&
	    !owner->quarantined && !owner->queued &&
	    kref_read(&owner->fl->refcount) == 1) {
		owner->queued = true;
		schedule_work(&owner->work);
	}
}

static void qkx_rpc_ctx_kick(struct qkx_rpc_ctx_owner *owner)
{
	if (owner->retire && !owner->operation && !owner->remote &&
	    !owner->unknown && !owner->callbacks && !owner->queued &&
	    !owner->finalizer) {
		owner->queued = true;
		schedule_work(&owner->work);
	}
}

static void qkx_rpc_file_worker(struct work_struct *work)
{
	struct qkx_rpc_file_owner *owner =
		container_of(work, struct qkx_rpc_file_owner, work);
	struct fastrpc_file *fl = owner->fl;
	unsigned long flags;
	int err = 0;
	bool release;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner->queued = false;
	if (owner->quarantined || owner->control_task ||
	    kref_read(&fl->refcount) != 1) {
		spin_unlock_irqrestore(&qkx_rpc_lock, flags);
		return;
	}
	owner->control_task = current;
	release = !owner->release_done;
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);

	/* Do not introduce timeouts for the original stack-backed control RPC. */
	if (release && fl->sctx)
		err = fastrpc_release_current_dsp_process(fl);

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner->control_task = NULL;
	if (err || owner->quarantined) {
		if (err)
			owner->release_error = err;
		owner->quarantined = true;
		spin_unlock_irqrestore(&qkx_rpc_lock, flags);
		return;
	}
	owner->release_done = true;
	if (kref_read(&fl->refcount) != 1) {
		/* A control context still owns its parent; its worker will kick us. */
		spin_unlock_irqrestore(&qkx_rpc_lock, flags);
		return;
	}
	list_del(&owner->node);
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);

	/* No new gets are possible after removing this sealed file's sidecar. */
	kref_put(&fl->refcount, fastrpc_file_destroy);
	kfree(owner);
}

static int qkx_rpc_file_create(struct fastrpc_file *fl)
{
	struct qkx_rpc_file_owner *owner;
	unsigned long flags;

	owner = kzalloc(sizeof(*owner), GFP_KERNEL);
	if (!owner)
		return -ENOMEM;
	owner->fl = fl;
	INIT_WORK(&owner->work, qkx_rpc_file_worker);
	kref_get(&fl->refcount); /* Real driver custodian, before publication. */
	spin_lock_irqsave(&qkx_rpc_lock, flags);
	list_add_tail(&owner->node, &qkx_rpc_files);
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return 0;
}

static int qkx_rpc_file_get(struct fastrpc_file *fl)
{
	struct qkx_rpc_file_owner *owner;
	unsigned long flags;
	int ret = 0;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_file_find(fl);
	if (owner && (!owner->close_requested ||
		      owner->control_task == current) && !owner->quarantined)
		ret = kref_get_unless_zero(&fl->refcount);
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return ret;
}

static void qkx_rpc_file_put(struct fastrpc_file *fl)
{
	struct qkx_rpc_file_owner *owner;
	unsigned long flags;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_file_find(fl);
	if (WARN_ON_ONCE(!owner || kref_read(&fl->refcount) <= 1)) {
		spin_unlock_irqrestore(&qkx_rpc_lock, flags);
		return;
	}
	/* The custodian prevents this put from becoming a destructor. */
	kref_put(&fl->refcount, fastrpc_file_destroy);
	qkx_rpc_file_kick(owner);
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
}

static void qkx_rpc_file_close(struct fastrpc_file *fl)
{
	struct qkx_rpc_file_owner *owner;
	struct qkx_rpc_ctx_owner *ctx;
	unsigned long flags;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_file_find(fl);
	if (owner) {
		owner->close_requested = true;
		list_for_each_entry(ctx, &qkx_rpc_contexts, node) {
			if (ctx->fl == fl && !ctx->operation) {
				ctx->retire = true;
				qkx_rpc_ctx_kick(ctx);
			}
		}
		qkx_rpc_file_kick(owner);
	}
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
}

static void qkx_rpc_file_lost(struct fastrpc_file *fl)
{
	struct qkx_rpc_file_owner *owner;
	struct qkx_rpc_ctx_owner *ctx;
	unsigned long flags;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_file_find(fl);
	if (owner) {
		owner->quarantined = true;
		owner->loss_error = -ECONNRESET;
	}
	list_for_each_entry(ctx, &qkx_rpc_contexts, node)
		if (ctx->fl == fl && !ctx->terminal)
			ctx->unknown = true;
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
}

static void qkx_rpc_ctx_worker(struct work_struct *work)
{
	struct qkx_rpc_ctx_owner *owner =
		container_of(work, struct qkx_rpc_ctx_owner, work);
	struct fastrpc_file *fl = owner->fl;
	unsigned long flags;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner->queued = false;
	if (!owner->retire || owner->operation || owner->remote ||
	    owner->unknown || owner->callbacks || owner->finalizer) {
		spin_unlock_irqrestore(&qkx_rpc_lock, flags);
		return;
	}
	owner->finalizer = current;
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);

	context_free(owner->ctx);
	spin_lock_irqsave(&qkx_rpc_lock, flags);
	list_del(&owner->node);
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	kfree(owner);
	/* The owning worker, never RX or an observer, discharges the parent. */
	fastrpc_file_put(fl);
}

static int qkx_rpc_ctx_create(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	struct qkx_rpc_file_owner *parent;
	unsigned long flags;

	owner = kzalloc(sizeof(*owner), GFP_KERNEL);
	if (!owner)
		return -ENOMEM;
	if (!fastrpc_file_get(ctx->fl)) {
		kfree(owner);
		return -ESHUTDOWN;
	}
	owner->ctx = ctx;
	owner->fl = ctx->fl;
	owner->operation = true;
	INIT_WORK(&owner->work, qkx_rpc_ctx_worker);
	spin_lock_irqsave(&qkx_rpc_lock, flags);
	parent = qkx_rpc_file_find(ctx->fl);
	if (!parent || parent->quarantined ||
	    (parent->close_requested && parent->control_task != current)) {
		spin_unlock_irqrestore(&qkx_rpc_lock, flags);
		fastrpc_file_put(ctx->fl);
		kfree(owner);
		return -ESHUTDOWN;
	}
	list_add_tail(&owner->node, &qkx_rpc_contexts);
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return 0;
}

static bool qkx_rpc_ctx_retire(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	unsigned long flags;
	bool destroy = false;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	if (owner) {
		destroy = owner->finalizer == current;
		if (!destroy) {
			owner->operation = false;
			owner->retire = true;
			qkx_rpc_ctx_kick(owner);
		}
	} else {
		WARN_ON_ONCE(1);
	}
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return destroy;
}

static void qkx_rpc_ctx_suspend(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	struct qkx_rpc_file_owner *parent;
	unsigned long flags;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	parent = qkx_rpc_file_find(ctx->fl);
	if (owner) {
		owner->operation = false;
		if (parent && parent->close_requested)
			owner->retire = true;
		qkx_rpc_ctx_kick(owner);
	}
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
}

static bool qkx_rpc_ctx_resume(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	unsigned long flags;
	bool resumed = false;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	if (owner && !owner->retire && !owner->operation && !owner->finalizer) {
		owner->operation = true;
		resumed = true;
	}
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return resumed;
}

static int qkx_rpc_ctx_send_begin(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	unsigned long flags;
	int err = -ESHUTDOWN;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	if (owner && owner->operation && !owner->retire &&
	    !owner->remote && !owner->unknown && !owner->terminal) {
		owner->remote = true; /* Before rpmsg_send can synchronously reply. */
		err = 0;
	}
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return err;
}

static void qkx_rpc_ctx_unknown(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	unsigned long flags;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	if (owner && !owner->terminal)
		owner->unknown = true;
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
}

static bool qkx_rpc_ctx_callback_begin(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	unsigned long flags;
	bool admitted = false;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	if (owner && owner->remote && !owner->finalizer &&
	    owner->callbacks != UINT_MAX) {
		owner->callbacks++;
		admitted = true;
	}
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return admitted;
}

static void qkx_rpc_ctx_complete(struct smq_invoke_ctx *ctx, bool callback,
				bool terminal)
{
	struct qkx_rpc_ctx_owner *owner;
	unsigned long flags;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	if (owner) {
		if (terminal && !owner->unknown) {
			owner->terminal = true;
			owner->remote = false;
		}
		if (callback && !WARN_ON_ONCE(!owner->callbacks))
			owner->callbacks--;
		qkx_rpc_ctx_kick(owner);
	}
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
}

static bool qkx_rpc_ctx_completed(struct smq_invoke_ctx *ctx)
{
	struct qkx_rpc_ctx_owner *owner;
	unsigned long flags;
	bool completed = false;

	spin_lock_irqsave(&qkx_rpc_lock, flags);
	owner = qkx_rpc_ctx_find(ctx);
	if (owner)
		completed = owner->terminal && !owner->unknown;
	spin_unlock_irqrestore(&qkx_rpc_lock, flags);
	return completed;
}
